// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // An arbitrary actor participates in the airdrop (same effect in P and M).
        vm.prank(actor);
        c.getTokens();
        assertTrue(c.blacklist(actor));

        // Owner initializes its own balance via XBornID (owner == deployer == this contract).
        c.XBornID();
        assertEq(c.balanceOf(address(this)), c.totalDistributed());

        // Owner receives an additional distribution: balances must ACCUMULATE,
        // so the owner's balance keeps matching the accumulated totalDistributed.
        c.getTokens();

        // General rule: balance of the repeatedly-credited account equals the
        // accumulated distribution total. Holds in P for every input;
        // the mutant's overwrite breaks it for every input.
        assertTrue(c.balanceOf(address(this)) == c.totalDistributed());
    }
}
